/* accent.css only themes :root, so a section previewing another preset restates its --primary pair. */
.bubbles-accent[data-accent] {
  --primary: var(--accent-primary-light);
  --primary-foreground: oklch(0.99 0 0);
  --ring: var(--primary);
}
.dark .bubbles-accent[data-accent] {
  --primary: var(--accent-primary-dark);
  --primary-foreground: oklch(0.205 0 0);
}

/* The global ::selection paints primary on a primary wash, which vanishes on a solid-accent bubble. */
[data-selection='soft']::selection,
[data-selection='soft'] *::selection {
  color: var(--primary-foreground);
  background-color: color-mix(in oklch, var(--primary-foreground) 28%, transparent);
}
[data-selection='invert']::selection,
[data-selection='invert'] *::selection {
  color: var(--primary);
  background-color: var(--primary-foreground);
}
[data-selection='punch']::selection,
[data-selection='punch'] *::selection {
  color: var(--foreground);
  background-color: var(--background);
}
